-- Consolida os pares já instalados somente se as configurações forem iguais.
-- Uma personalização divergente exige revisão, em vez de perda silenciosa.
DO $$
DECLARE p modelo_reuniao%ROWTYPE; d modelo_reuniao%ROWTYPE;
BEGIN
  FOR p IN
    SELECT m.* FROM modelo_reuniao m
    JOIN contexto_secretaria c ON c.id=m.contexto_id AND c.igreja_id=m.igreja_id
    JOIN orgao_interno o ON o.id=c.orgao_id AND o.igreja_id=c.igreja_id
    WHERE o.tipo_padrao='ASSEMBLEIA_GERAL' AND m.finalidade='Eleição de presbíteros'
  LOOP
    SELECT * INTO d FROM modelo_reuniao
    WHERE contexto_id=p.contexto_id AND igreja_id=p.igreja_id AND finalidade='Eleição de diáconos';
    IF d.id IS NULL OR d.configuracao IS DISTINCT FROM p.configuracao THEN
      RAISE EXCEPTION 'Modelos eleitorais divergentes no contexto %. Revisão necessária.', p.contexto_id;
    END IF;
    IF EXISTS (SELECT 1 FROM modelo_reuniao WHERE contexto_id=p.contexto_id AND finalidade='Eleição de oficiais') THEN
      RAISE EXCEPTION 'Modelo Eleição de oficiais já existe no contexto %. Revisão necessária.', p.contexto_id;
    END IF;
    UPDATE modelo_reuniao SET finalidade='Eleição de oficiais', revisao=revisao+1 WHERE id=p.id;
    -- Os retratos históricos conservam a finalidade e a revisão da vinculação original.
    UPDATE reuniao SET dados=jsonb_set(dados,'{modelo_reuniao_id}',to_jsonb(p.id)), revisao=revisao+1
    WHERE igreja_id=p.igreja_id AND contexto_id=p.contexto_id AND dados->>'modelo_reuniao_id'=d.id;
    DELETE FROM modelo_reuniao WHERE id=d.id AND igreja_id=p.igreja_id;
  END LOOP;
END $$;
COMMIT;
